/// <summary>
/// CB167_PerformStockReservation
/// This is a controller class for reserve event orders batch job.
/// </summary>
class METSalesOrderGuideCheckController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
/// Sets service and its method.
/// </summary>
protected void new()
{
    super(classstr(METSalesOrderGuideCheckService), methodstr(METSalesOrderGuideCheckService, process), SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// Sets caption for the batch job.
/// </summary>
/// <returns>Caption.</returns>
protected ClassDescription defaultCaption()
{
    return "@MET:SalesOrderGuideCheck";
}

/// <summary>
/// Starts the batch job processing.
/// </summary>
/// <param name = "_args">
/// <c>Args</c>.
/// </param>
public static void main(Args _args)
{
    METSalesOrderGuideCheckController controller = new METSalesOrderGuideCheckController();

    controller.parmArgs(_args);
    controller.parmLoadFromSysLastValue(false);
    controller.startOperation();
}
